export const dtcAnalyzerMessageCatalog = Object.fromEntries(
  dtcAnalyzerMessageRows.map(([key, ...translations]) => [
    key,
    Object.fromEntries(dtcAnalyzerLocaleOrder.map((locale, index) => [locale, translations[index]])),
  ])
) as Record<DtcAnalyzerMessageKey, Record<LocaleCode, string>>;

function interpolate(template: string, params: DtcAnalyzerMessageDescriptor["params"]) {
  if (!params) return template;
  return template.replace(/\{([a-zA-Z][a-zA-Z0-9]*)\}/g, (token, key: string) => {
    const value = params[key];
    return value === undefined ? token : String(value);
  });
}

export function localizeDtcAnalyzerMessage(
  locale: LocaleCode,
  descriptor: DtcAnalyzerMessageDescriptor
) {
  const template = dtcAnalyzerMessageCatalog[descriptor.key]?.[locale] ?? descriptor.fallback;
  return interpolate(template, descriptor.params);
}

export function localizeDtcConfidence(locale: LocaleCode, confidence: DtcAnalyzerConfidence) {
  return localizeDtcAnalyzerMessage(locale, {
    key: `confidence.${confidence}`,
    fallback: confidence === "none"
      ? "None"
      : confidence === "low"
        ? "Low"
        : confidence === "medium"
          ? "Medium"
          : "High",
  });
}
